import type { AdminModelCardBulkDeleteMutation } from '../__generated__/AdminModelCardBulkDeleteMutation.graphql';
import type { AdminModelCardDeleteMutation } from '../__generated__/AdminModelCardDeleteMutation.graphql';
import type {
  AdminModelCardQuery as AdminModelCardQueryType,
  AdminModelCardQuery$data,
  ModelCardV2Filter,
  ModelCardV2OrderBy,
} from '../__generated__/AdminModelCardQuery.graphql';
import { App } from '../app-shim';
import {
  convertFirstOrderByToString,
  convertToOrderBy,
  handleRowSelectionChange,
} from '../helper';
import { buildPath } from '../helper/pathBuilder';
import { useSuspendedBackendaiClient } from '../hooks';
import { useSetBAINotification } from '../hooks/useBAINotification';
import AdminModelCardSettingModal from './AdminModelCardSettingModal';
import { useFolderExplorerOpener } from './FolderExplorerOpener';
import VFolderNodeIdenticonV2 from './VFolderNodeIdenticonV2';
import { Text } from '@lablup/ui-common/Text';
import { Token } from '@lablup/ui-common/Token';
import { Tooltip } from '@lablup/ui-common/Tooltip';
import { useTheme } from '@lablup/ui-common/theme';
import {
  BAIAdminProjectSelect,
  BAIAlert,
  BAIButton,
  BAIColumnType,
  BAIDeleteConfirmModal,
  BAIFetchKeyButton,
  BAIFlex,
  BAIGraphQLPropertyFilter,
  BAILink,
  BAINameActionCell,
  BAISelectionLabel,
  BAIStorageHostSelect,
  BAITable,
  BAIText,
  BAIUnmountAfterClose,
  filterOutEmpty,
  filterOutNullAndUndefined,
  isValidUUID,
  tokenColorForTagColor,
  useBAILogger,
  type BAITableSettings,
  BAICheckboxInput,
} from 'backend.ai-ui';
import dayjs from 'dayjs';
import * as _ from 'lodash-es';
import { CircleAlert, PlusIcon, SquarePenIcon, Trash2 } from 'lucide-react';
import React, { useDeferredValue, useState } from 'react';
import { useTranslation } from 'react-i18next';
import {
  PreloadedQuery,
  UseQueryLoaderLoadQueryOptions,
  graphql,
  useMutation,
  usePreloadedQuery,
} from 'react-relay';

type ModelCardNode = NonNullableNodeOnEdges<
  AdminModelCardQuery$data['adminModelCardsV2']
>;

const availableModelCardSorterKeys = [
  'name',
  'created_at',
  // Opened by 26.9.0 (backend #14811); gated on that manager version.
  'title',
  'category',
  'task',
  'access_level',
  'project_id',
] as const;

export const availableModelCardSorterValues = [
  ...availableModelCardSorterKeys,
  ...availableModelCardSorterKeys.map((key) => `-${key}` as const),
] as const;

export const AdminModelCardQuery = graphql`
  query AdminModelCardQuery(
    $filter: ModelCardV2Filter
    $orderBy: [ModelCardV2OrderBy!]
    $limit: Int
    $offset: Int
    $domainName: String
  ) {
    adminModelCardsV2(
      filter: $filter
      orderBy: $orderBy
      limit: $limit
      offset: $offset
    ) {
      count
      edges {
        node {
          id
          entityId
          name
          vfolderId
          vfolder {
            id
            metadata {
              name
            }
            ...VFolderNodeIdenticonV2Fragment
          }
          projectId
          project {
            id
            basicInfo {
              name
            }
          }
          accessLevel
          createdAt
          updatedAt
          metadata {
            title
            category
            task
          }
          ...AdminModelCardSettingModalFragment
        }
      }
    }
    groups(domain_name: $domainName, is_active: true, type: ["MODEL_STORE"]) {
      id
      name
    }
  }
`;

export interface AdminModelCardProps {
  queryRef: PreloadedQuery<AdminModelCardQueryType>;
  /** The user's conditions, without the page's domain scoping. */
  filter?: ModelCardV2Filter;
  onReload: (
    variables: AdminModelCardQueryType['variables'],
    options?: UseQueryLoaderLoadQueryOptions,
  ) => void;
  tableSettings: BAITableSettings;
}

const AdminModelCard: React.FC<AdminModelCardProps> = ({
  queryRef,
  filter,
  onReload,
  tableSettings,
}) => {
  'use memo';

  const { t } = useTranslation();
  const { message } = App.useApp();
  const { token } = useTheme();
  const { logger } = useBAILogger();
  const { upsertNotification } = useSetBAINotification();
  const { generateFolderPath } = useFolderExplorerOpener();
  const baiClient = useSuspendedBackendaiClient();
  // 26.9.0 opened the metadata axes of the model card search (backend #14811).
  const supportsSearchAxes = baiClient.isManagerVersionCompatibleWith('26.9.0');

  const [isSettingModalOpen, setIsSettingModalOpen] = useState(false);
  const [editingModelCardId, setEditingModelCardId] = useState<string | null>(
    null,
  );
  const [selectedModelCards, setSelectedModelCards] = useState<ModelCardNode[]>(
    [],
  );
  const [deletingModelCard, setDeletingModelCard] =
    useState<ModelCardNode | null>(null);
  const [alsoDeleteFolder, setAlsoDeleteFolder] = useState(false);
  const [isBulkDeleteOpen, setIsBulkDeleteOpen] = useState(false);
  const [alsoDeleteFoldersBulk, setAlsoDeleteFoldersBulk] = useState(false);

  const order = convertFirstOrderByToString(queryRef.variables.orderBy);
  const pageSize = queryRef.variables.limit ?? 10;
  const offset = queryRef.variables.offset ?? 0;
  const current = pageSize ? Math.floor(offset / pageSize) + 1 : 1;

  const deferredQueryRef = useDeferredValue(queryRef);
  const isRefetching = deferredQueryRef !== queryRef;

  const { adminModelCardsV2, groups } =
    usePreloadedQuery<AdminModelCardQueryType>(
      AdminModelCardQuery,
      deferredQueryRef,
    );

  const [commitDeleteModelCard] = useMutation<AdminModelCardDeleteMutation>(
    graphql`
      mutation AdminModelCardDeleteMutation(
        $id: UUID!
        $options: DeleteModelCardV2Options
      ) {
        adminDeleteModelCardV2(id: $id, options: $options) {
          id
        }
      }
    `,
  );

  const [commitBulkDeleteModelCards, isBulkDeleteInFlight] =
    useMutation<AdminModelCardBulkDeleteMutation>(graphql`
      mutation AdminModelCardBulkDeleteMutation(
        $input: BulkDeleteModelCardsV2Input!
      ) {
        adminBulkDeleteModelCardsV2(input: $input) {
          successes
          failed {
            cardId
            message
          }
        }
      }
    `);

  const handleDeleteModelCard = (modelCard: ModelCardNode) => {
    setDeletingModelCard(modelCard);
  };

  const handleBulkDelete = () => {
    if (selectedModelCards.length === 0) return;
    setIsBulkDeleteOpen(true);
  };

  const handleOpenEditModal = (modelCard: ModelCardNode) => {
    setEditingModelCardId(modelCard.id);
    setIsSettingModalOpen(true);
  };

  const handleOpenCreateModal = () => {
    setEditingModelCardId(null);
    setIsSettingModalOpen(true);
  };

  const modelCards = adminModelCardsV2?.edges?.map((edge) => edge?.node) ?? [];

  const editingModelCard = editingModelCardId
    ? modelCards.find((mc) => mc?.id === editingModelCardId)
    : null;

  const columns: BAIColumnType<ModelCardNode>[] = filterOutEmpty([
    {
      key: 'name',
      title: t('adminModelCard.Name'),
      dataIndex: 'name',
      sorter: true,
      fixed: 'left' as const,
      render: (name, modelCard) => (
        <BAINameActionCell
          title={name}
          showActions="always"
          actions={[
            {
              key: 'edit',
              title: t('button.Edit'),
              icon: <SquarePenIcon />,
              onClick: () => handleOpenEditModal(modelCard),
            },
            {
              key: 'delete',
              title: t('button.Delete'),
              icon: <Trash2 size="1em" />,
              type: 'danger' as const,
              onClick: () => handleDeleteModelCard(modelCard),
            },
          ]}
        />
      ),
    },
    {
      key: 'title',
      title: t('adminModelCard.Title'),
      sorter: supportsSearchAxes,
      render: (_, record) =>
        record.metadata?.title ? (
          <Text maxLines={1} style={{ maxWidth: 200 }}>
            {record.metadata.title}
          </Text>
        ) : (
          '-'
        ),
    },
    {
      key: 'category',
      title: t('modelStore.Category'),
      sorter: supportsSearchAxes,
      render: (_, record) => record.metadata?.category || '-',
    },
    {
      key: 'task',
      title: t('modelStore.Task'),
      sorter: supportsSearchAxes,
      render: (_, record) => record.metadata?.task || '-',
    },
    {
      key: 'accessLevel',
      title: t('adminModelCard.AccessLevel'),
      dataIndex: 'accessLevel',
      sorter: supportsSearchAxes,
      render: (accessLevel) => (
        <Token
          color={tokenColorForTagColor(
            accessLevel === 'PUBLIC' ? 'green' : 'default',
          )}
          label={
            accessLevel === 'PUBLIC'
              ? t('adminModelCard.Public')
              : t('adminModelCard.Private')
          }
        />
      ),
    },
    // TODO(needs-backend): FR-2417 - Add minResource column when ModelCardV2Metadata includes minResource field
    {
      key: 'projectId',
      title: t('adminModelCard.Project'),
      dataIndex: 'projectId',
      sorter: supportsSearchAxes,
      // Fall back to the raw UUID when the project name does not resolve.
      render: (projectId, record) => {
        const projectName = record.project?.basicInfo?.name;
        if (!projectName) {
          return (
            <BAIText
              copyable
              ellipsis={{ tooltip: true }}
              style={{ maxWidth: 150 }}
            >
              {projectId}
            </BAIText>
          );
        }
        return (
          <BAIText
            ellipsis={{ tooltip: projectName }}
            style={{ maxWidth: 150 }}
          >
            {projectName}
          </BAIText>
        );
      },
    },
    {
      key: 'createdAt',
      title: t('general.CreatedAt'),
      dataIndex: 'createdAt',
      sorter: true,
      render: (createdAt) =>
        createdAt ? dayjs(createdAt).format('YYYY-MM-DD HH:mm') : '-',
    },
    {
      key: 'updatedAt',
      title: t('general.ModifiedAt'),
      dataIndex: 'updatedAt',
      defaultHidden: true,
      render: (updatedAt) =>
        updatedAt ? dayjs(updatedAt).format('YYYY-MM-DD HH:mm') : '-',
    },
  ]);

  return (
    <BAIFlex direction="column" align="stretch" gap={'sm'}>
      <BAIFlex justify="between" wrap="wrap" gap={'sm'}>
        <BAIFlex gap={'sm'} align="start" wrap="wrap" style={{ flexShrink: 1 }}>
          <BAIGraphQLPropertyFilter<ModelCardV2Filter>
            filterProperties={filterOutEmpty([
              {
                key: 'name',
                propertyLabel: t('adminModelCard.Name'),
                type: 'string',
              },
              supportsSearchAxes && {
                key: 'title',
                propertyLabel: t('adminModelCard.Title'),
                type: 'string',
              },
              supportsSearchAxes && {
                key: 'category',
                propertyLabel: t('modelStore.Category'),
                type: 'string',
              },
              supportsSearchAxes && {
                key: 'task',
                propertyLabel: t('modelStore.Task'),
                type: 'string',
              },
              {
                key: 'projectId',
                propertyLabel: t('adminModelCard.Project'),
                type: 'uuid' as const,
                rule: {
                  message: t('project.ProjectIDFilterRuleMessage'),
                  validate: (value) => isValidUUID(value),
                },
                renderInput: ({ onAddCondition, value, isDisabled }) => (
                  <BAIAdminProjectSelect
                    label={t('adminModelCard.Project')}
                    isLabelHidden
                    // A model card belongs to a MODEL_STORE project (see the
                    // `groups(type: ["MODEL_STORE"])` query above).
                    filter={{ type: { equals: 'MODEL_STORE' } }}
                    value={value}
                    isDisabled={isDisabled}
                    onChange={(next, option) =>
                      onAddCondition(
                        next as string | undefined,
                        Array.isArray(option)
                          ? option[0]?.label
                          : option?.label,
                      )
                    }
                  />
                ),
              },
              {
                // Deprecated since 26.9.0 in favour of `usedBy.vfolder`, which
                // a filter row cannot fill without an unbounded id fan-out.
                // FR-4014 settles the replacement with CoreDev.
                key: 'storageHost',
                propertyLabel: t('import.StorageHost'),
                type: 'string',
                operators: ['equals', 'notEquals'],
                defaultOperator: 'equals',
                renderInput: ({ onAddCondition, value, isDisabled }) => (
                  <BAIStorageHostSelect
                    // The filter row already prints the property label.
                    label={t('import.StorageHost')}
                    isLabelHidden
                    value={value}
                    isDisabled={isDisabled}
                    onChange={(value) =>
                      // Single-select mode (no `multiple` prop) always emits a
                      // single value.
                      onAddCondition(value as string | undefined)
                    }
                  />
                ),
              },
              supportsSearchAxes && {
                key: 'accessLevel',
                propertyLabel: t('adminModelCard.AccessLevel'),
                type: 'enum',
                strictSelection: true,
                // `accessLevel` is a StringFilter over the stored text, which is
                // the lowercase enum value: 'public' / 'internal'.
                options: [
                  { label: t('adminModelCard.Public'), value: 'public' },
                  { label: t('adminModelCard.Private'), value: 'internal' },
                ],
              },
              supportsSearchAxes && {
                key: 'createdAt',
                propertyLabel: t('general.CreatedAt'),
                type: 'datetime',
                defaultOperator: 'after',
              },
            ])}
            value={filter}
            onChange={(value) => {
              onReload(
                {
                  ...queryRef.variables,
                  filter: value ?? undefined,
                  offset: 0,
                },
                { fetchPolicy: 'network-only' },
              );
            }}
          />
        </BAIFlex>
        <BAIFlex gap={'xs'}>
          {selectedModelCards.length > 0 && (
            <>
              <BAISelectionLabel
                count={selectedModelCards.length}
                onClearSelection={() => setSelectedModelCards([])}
              />
              <BAIButton
                icon={
                  <Trash2
                    style={{ color: token('--color-error') }}
                    size="1em"
                  />
                }
                onClick={handleBulkDelete}
                loading={isBulkDeleteInFlight}
              />
            </>
          )}
          <BAIFetchKeyButton
            loading={isRefetching}
            onChange={() =>
              onReload(queryRef.variables, { fetchPolicy: 'network-only' })
            }
          />
          <BAIButton
            type="primary"
            icon={<PlusIcon />}
            onClick={handleOpenCreateModal}
          >
            {t('adminModelCard.CreateModelCard')}
          </BAIButton>
        </BAIFlex>
      </BAIFlex>
      <BAITable<ModelCardNode>
        scroll={{ x: 'max-content' }}
        rowKey="id"
        dataSource={modelCards as ModelCardNode[]}
        columns={columns}
        loading={isRefetching}
        order={order}
        rowSelection={{
          type: 'checkbox',
          preserveSelectedRowKeys: true,
          onChange: (selectedRowKeys) => {
            handleRowSelectionChange(
              selectedRowKeys,
              filterOutNullAndUndefined(modelCards),
              setSelectedModelCards,
            );
          },
          selectedRowKeys: _.map(selectedModelCards, (i) => i.id),
        }}
        onChangeOrder={(order) => {
          onReload(
            {
              ...queryRef.variables,
              orderBy: convertToOrderBy<ModelCardV2OrderBy>(order),
              offset: 0,
            },
            { fetchPolicy: 'network-only' },
          );
        }}
        tableSettings={tableSettings}
        pagination={{
          pageSize,
          current,
          total: adminModelCardsV2?.count ?? 0,
          onChange: (nextCurrent, nextPageSize) => {
            onReload(
              {
                ...queryRef.variables,
                limit: nextPageSize,
                offset: nextCurrent > 1 ? (nextCurrent - 1) * nextPageSize : 0,
              },
              { fetchPolicy: 'network-only' },
            );
          },
        }}
      />
      <BAIUnmountAfterClose>
        <AdminModelCardSettingModal
          open={isSettingModalOpen}
          modelCardFrgmt={editingModelCard ?? null}
          modelStoreProject={groups?.[0] ?? null}
          onRequestClose={(success) => {
            setIsSettingModalOpen(false);
            setEditingModelCardId(null);
            // A create adds a new row the offset query can't know about, so it
            // needs a refetch. An update returns every field, so Relay merges
            // the record by id into the store and the list reflects it
            // without one.
            if (success && editingModelCard === null) {
              onReload(queryRef.variables, { fetchPolicy: 'network-only' });
            }
          }}
        />
      </BAIUnmountAfterClose>
      <BAIDeleteConfirmModal
        open={!!deletingModelCard}
        items={
          deletingModelCard
            ? [{ key: deletingModelCard.id, label: deletingModelCard.name }]
            : []
        }
        title={t('adminModelCard.DeleteModelCard')}
        description={t('adminModelCard.ConfirmDelete', {
          name: deletingModelCard?.name,
        })}
        requireConfirmInput
        extraContent={
          <BAIFlex direction="column" align="stretch" gap="xs">
            <BAIFlex align="start" gap="xs">
              <Tooltip
                content={t('adminModelCard.AlsoDeleteModelFolderTooltip')}
              >
                {/* The adjacent visible text is the checkbox label now —
                    CheckboxInput renders it itself. */}
                <BAICheckboxInput
                  value={alsoDeleteFolder}
                  onChange={(checked) => setAlsoDeleteFolder(checked)}
                >
                  {t('adminModelCard.AlsoDeleteModelFolder')}
                </BAICheckboxInput>
              </Tooltip>
              {deletingModelCard?.vfolder && (
                <span>
                  {'('}
                  <VFolderNodeIdenticonV2
                    vfolderNodeIdenticonFrgmt={deletingModelCard.vfolder}
                    style={{
                      verticalAlign: 'middle',
                      marginInline: token('--spacing-1'),
                    }}
                  />
                  <BAILink
                    to={generateFolderPath(deletingModelCard.vfolderId)}
                    onClick={(e) => e.stopPropagation()}
                  >
                    {deletingModelCard.vfolder.metadata.name}
                  </BAILink>
                  {')'}
                </span>
              )}
            </BAIFlex>
            {alsoDeleteFolder && (
              <BAIAlert
                type="error"
                icon={<CircleAlert size="1em" />}
                showIcon
                description={t(
                  'adminModelCard.AlsoDeleteModelFolderCascadeWarning',
                )}
              />
            )}
          </BAIFlex>
        }
        onOk={() => {
          if (deletingModelCard) {
            return new Promise<void>((resolve, reject) => {
              const vfolderId = deletingModelCard.vfolderId;
              const folderName = deletingModelCard.vfolder?.metadata.name;
              const folderTrashSearch = new URLSearchParams({
                statusCategory: 'deleted',
                filter: folderName
                  ? `name == "${folderName}"`
                  : `id == "${vfolderId}"`,
              }).toString();

              commitDeleteModelCard({
                variables: {
                  id: deletingModelCard.entityId,
                  options: { deleteAssociatedVfolder: alsoDeleteFolder },
                },
                onCompleted: (_data, errors) => {
                  if (errors && errors.length > 0) {
                    logger.error(errors[0]);
                    message.error(
                      errors[0]?.message || t('general.ErrorOccurred'),
                    );
                    reject();
                    return;
                  }

                  if (alsoDeleteFolder) {
                    upsertNotification({
                      type: 'success',
                      message: t('adminModelCard.ModelCardAndFolderDeleted'),
                      to: {
                        pathname: buildPath('admin', 'data'),
                        search: folderTrashSearch,
                      },
                      toText: t('adminModelCard.GoToTrash'),
                      open: true,
                      extraData: null,
                    });
                  } else {
                    message.success(
                      t('adminModelCard.ModelCardDeletedFolderKept'),
                    );
                  }

                  setDeletingModelCard(null);
                  setAlsoDeleteFolder(false);
                  onReload(queryRef.variables, {
                    fetchPolicy: 'network-only',
                  });
                  resolve();
                },
                onError: (error) => {
                  logger.error(error);
                  message.error(error?.message || t('general.ErrorOccurred'));
                  reject();
                },
              });
            });
          }
        }}
        onCancel={() => {
          setDeletingModelCard(null);
          setAlsoDeleteFolder(false);
        }}
      />
      <BAIDeleteConfirmModal
        open={isBulkDeleteOpen}
        confirmLoading={isBulkDeleteInFlight}
        items={selectedModelCards.map((mc) => ({
          key: mc.id,
          label: mc.name,
        }))}
        title={t('adminModelCard.BulkDeleteModelCards')}
        description={t('adminModelCard.ConfirmBulkDelete', {
          count: selectedModelCards.length,
        })}
        extraContent={
          <BAIFlex direction="column" align="stretch" gap="xs">
            <BAIFlex align="center" gap="xs">
              <Tooltip
                content={t('adminModelCard.AlsoDeleteModelFolderTooltip')}
              >
                {/* The adjacent visible text is the checkbox label now —
                    CheckboxInput renders it itself. */}
                <BAICheckboxInput
                  value={alsoDeleteFoldersBulk}
                  onChange={(checked) => setAlsoDeleteFoldersBulk(checked)}
                >
                  {t('adminModelCard.AlsoDeleteModelFolders')}
                </BAICheckboxInput>
              </Tooltip>
            </BAIFlex>
            {alsoDeleteFoldersBulk && (
              <BAIAlert
                type="error"
                icon={<CircleAlert size="1em" />}
                showIcon
                description={t(
                  'adminModelCard.AlsoDeleteModelFoldersCascadeWarning',
                )}
              />
            )}
          </BAIFlex>
        }
        onOk={() => {
          const ids = selectedModelCards.map((mc) => mc.entityId);
          return new Promise<void>((resolve, reject) => {
            commitBulkDeleteModelCards({
              variables: {
                input: {
                  ids,
                  options: { deleteAssociatedVfolder: alsoDeleteFoldersBulk },
                },
              },
              onCompleted: (data, errors) => {
                if (errors && errors.length > 0) {
                  logger.error(errors[0]);
                  message.error(
                    errors[0]?.message || t('general.ErrorOccurred'),
                  );
                  reject();
                  return;
                }
                const { successes, failed } =
                  data.adminBulkDeleteModelCardsV2 ?? {
                    successes: [],
                    failed: [],
                  };
                if (failed.length > 0) {
                  const failedIds = new Set(
                    failed.map((f: { cardId: string }) => f.cardId),
                  );
                  setSelectedModelCards(
                    selectedModelCards.filter((mc) =>
                      failedIds.has(mc.entityId),
                    ),
                  );
                  upsertNotification({
                    type: 'warning',
                    message: t('adminModelCard.BulkDeletePartiallyCompleted', {
                      successCount: successes.length,
                      failureCount: failed.length,
                    }),
                    description: (
                      <BAIFlex direction="column" gap="xs">
                        {failed.map((f) => {
                          const cardName =
                            selectedModelCards.find(
                              (mc) => mc.entityId === f.cardId,
                            )?.name ?? f.cardId;
                          return (
                            <div key={f.cardId}>
                              <Text weight="semibold">{cardName}</Text>
                              <Text color="secondary">{' — '}</Text>
                              <Text type="supporting" color="primary">
                                {f.message}
                              </Text>
                            </div>
                          );
                        })}
                      </BAIFlex>
                    ),
                    open: true,
                    duration: 0,
                    extraData: null,
                  });
                } else if (alsoDeleteFoldersBulk) {
                  upsertNotification({
                    type: 'success',
                    message: t(
                      'adminModelCard.BulkDeleteModelCardsAndFoldersCompleted',
                      { count: successes.length },
                    ),
                    to: {
                      pathname: buildPath('admin', 'data'),
                      search: new URLSearchParams({
                        statusCategory: 'deleted',
                      }).toString(),
                    },
                    toText: t('adminModelCard.GoToTrash'),
                    open: true,
                    extraData: null,
                  });
                  setSelectedModelCards([]);
                } else {
                  message.success(
                    t('adminModelCard.BulkDeleteCompleted', {
                      count: successes.length,
                    }),
                  );
                  setSelectedModelCards([]);
                }
                setAlsoDeleteFoldersBulk(false);
                setIsBulkDeleteOpen(false);
                onReload(queryRef.variables, { fetchPolicy: 'network-only' });
                resolve();
              },
              onError: (error) => {
                logger.error(error);
                message.error(error?.message || t('general.ErrorOccurred'));
                reject();
              },
            });
          });
        }}
        onCancel={() => {
          setIsBulkDeleteOpen(false);
          setAlsoDeleteFoldersBulk(false);
        }}
      />
    </BAIFlex>
  );
};

export default AdminModelCard;
